/// L'officine vient de la base, et la base l'apprend du premier poste
/// qui l'ouvre.
///
/// `config.toml` est un fichier **par PC**. L'identité de l'officine et
/// son équipe, elles, valent pour l'officine : l'équipe déclarée sur le
/// poste du comptoir n'existait pas sur celui de l'arrière-boutique, et
/// le nom de la pharmacie se retapait sur chacun. C'est la raison qui
/// avait déjà fait mettre les notes d'équipe et les scripts à côté de la
/// base plutôt qu'à côté de la configuration — la base est ce que les
/// postes partagent.
///
/// **Rien n'est perdu à la reprise** : une base qui n'en porte pas
/// encore reçoit ce que ce poste avait dans son fichier. Le premier
/// lancement de la nouvelle version verse donc ce qui était déjà écrit,
/// et les postes suivants le lisent au lieu de le redemander.
fn adopt_officine(config: &mut Config, session: &mut Session) {
    match session.db.officine() {
        Some(shared) => {
            config.pharmacy = shared.clone();
            session.officine_seen = Some(shared);
        }
        None => {
            let day = session.today.clone();
            if session
                .db
                .set_officine(&config.pharmacy, None, &day, "")
                .unwrap_or(false)
            {
                session.officine_seen = Some(config.pharmacy.clone());
            }
        }
    }
}

/// Run [`daily_backup`] on a background thread with its own connection:
/// `VACUUM INTO` rewrites the whole encrypted file, and doing that
/// synchronously over a network share would freeze the UI at unlock.
fn spawn_daily_backup(
    db_path: std::path::PathBuf,
    password: String,
    keep: usize,
    scans_keep: usize,
) {
    if keep == 0 && scans_keep == 0 {
        return;
    }
    std::thread::spawn(move || {
        if let Ok(db) = Db::open(&db_path, &password) {
            daily_backup(&db, &db_path, keep);
            daily_scans_backup(&db, &db_path, scans_keep);
            daily_stups_backup(&db, &db_path, keep.max(scans_keep));
        }
    });
}

/// La copie quotidienne du registre.
///
/// Elle suit le **plus grand** des deux comptes, et non le sien : le
/// registre pèse quelques centaines de kilo-octets pour dix ans, donc
/// rien ne se gagne à en garder moins, et c'est le seul fichier de la
/// maison qu'on ne peut pas reconstituer — une base perdue se ressème,
/// un registre perdu ne se retrouve nulle part.
fn daily_stups_backup(db: &Db, db_path: &std::path::Path, keep: usize) {
    if keep == 0 {
        return;
    }
    // Rien à copier tant que le registre est vide : la plupart des
    // officines suivront leur premier produit des semaines après
    // l'installation, et recopier un fichier vide tous les jours
    // n'apprend rien à personne.
    if db.stup_weight().map(|(_, lines, _, _)| lines) == Ok(0) {
        return;
    }
    let Ok(today) = db.today_iso() else { return };
    let dir = db::backup_dir(db_path);
    let target = dir.join(db::stups_backup_name(&today));
    if target.exists() {
        return;
    }
    if let Err(e) = std::fs::create_dir_all(&dir) {
        eprintln!("bpm-caddy : dossier de sauvegarde inaccessible : {e}");
        return;
    }
    if let Err(e) = db.backup_stups_to(&target) {
        eprintln!("bpm-caddy : {e}");
        return;
    }
    let mut backups: Vec<_> = std::fs::read_dir(&dir)
        .map(|rd| {
            rd.filter_map(|e| e.ok().map(|e| e.path()))
                .filter(|p| {
                    p.file_name()
                        .and_then(|n| n.to_str())
                        .is_some_and(|n| n.starts_with("bpm_caddy_stups-") && n.ends_with(".db"))
                })
                .collect()
        })
        .unwrap_or_default();
    backups.sort();
    while backups.len() > keep {
        let _ = std::fs::remove_file(backups.remove(0));
    }
}

/// La copie quotidienne du fichier des pièces, sur son propre compte.
///
/// Séparée de celle de la base, et pas par symétrie : c'est le fichier
/// qui pèse. Quatorze copies d'une base de six mégaoctets coûtent
/// quatre-vingt-dix mégaoctets ; quatorze copies d'un fichier de pièces
/// d'un an en coûtent dix mille. L'officine choisit combien elle en
/// garde (`[scans] backups_keep`, deux par défaut), et le choix est
/// possible parce que les deux fichiers sont séparés.
fn daily_scans_backup(db: &Db, db_path: &std::path::Path, keep: usize) {
    if keep == 0 {
        return;
    }
    // Rien à copier tant que personne n'a rangé de pièce : un fichier
    // vide recopié tous les jours n'apprend rien à personne.
    if db.scan_weight().map(|(n, _)| n) == Ok(0) {
        return;
    }
    let Ok(today) = db.today_iso() else { return };
    let dir = db::backup_dir(db_path);
    let target = dir.join(db::scans_backup_name(&today));
    if target.exists() {
        return;
    }
    if let Err(e) = std::fs::create_dir_all(&dir) {
        eprintln!("bpm-caddy : dossier de sauvegarde inaccessible : {e}");
        return;
    }
    if let Err(e) = db.backup_scans_to(&target) {
        eprintln!("bpm-caddy : {e}");
        return;
    }
    let mut backups: Vec<_> = std::fs::read_dir(&dir)
        .map(|rd| {
            rd.filter_map(|e| e.ok().map(|e| e.path()))
                .filter(|p| {
                    p.file_name()
                        .and_then(|n| n.to_str())
                        .is_some_and(|n| n.starts_with("bpm_caddy_scans-") && n.ends_with(".db"))
                })
                .collect()
        })
        .unwrap_or_default();
    backups.sort();
    while backups.len() > keep {
        let _ = std::fs::remove_file(backups.remove(0));
    }
}

/// One backup per day, in `backups/` next to the database, pruned to
/// the newest `keep` (0 disables). Runs after each successful unlock.
/// Failures only go to stderr: a failed backup must never block the
/// counter workflow, and on a shared drive another PC may have made
/// today's copy already.
fn daily_backup(db: &Db, db_path: &std::path::Path, keep: usize) {
    if keep == 0 {
        return;
    }
    let Ok(today) = db.today_iso() else { return };
    let dir = db::backup_dir(db_path);
    let target = dir.join(db::backup_name(&today));
    if target.exists() {
        return;
    }
    if let Err(e) = std::fs::create_dir_all(&dir) {
        eprintln!("bpm-caddy : dossier de sauvegarde inaccessible : {e}");
        return;
    }
    if let Err(e) = db.backup_to(&target) {
        eprintln!("bpm-caddy : {e}");
        return;
    }
    // Date-named files sort chronologically: drop the oldest past `keep`.
    let mut backups: Vec<_> = std::fs::read_dir(&dir)
        .map(|rd| {
            rd.filter_map(|e| e.ok().map(|e| e.path()))
                .filter(|p| {
                    p.file_name()
                        .and_then(|n| n.to_str())
                        .is_some_and(|n| n.starts_with("bpm_caddy-") && n.ends_with(".db"))
                })
                .collect()
        })
        .unwrap_or_default();
    backups.sort();
    while backups.len() > keep {
        let _ = std::fs::remove_file(backups.remove(0));
    }
}

/// Build the billing-reconciliation CSV: BOM + semicolons for French
/// Excel, dates in JJ/MM/AAAA, decimal comma for the fees.
fn interviews_csv(rows: &[db::ExportRow], config: &Config) -> String {
    fn field(s: &str) -> String {
        if s.contains([';', '"', '\n', '\r']) {
            format!("\"{}\"", s.replace('"', "\"\""))
        } else {
            s.to_owned()
        }
    }
    let mut out = String::from(
        "\u{feff}Patient;Téléphone;Naissance;Type;Code acte;Année;Étape;Thème;État;Fait le;Par;\
         RDV;Durée (min);À distance;Changement de traitement;Situation;Honoraires (€);\
         Prise en charge (%);Facturé (€)\r\n",
    );
    for r in rows {
        let comma = |v: f64| format!("{v:.2}").replace('.', ",");
        // "Honoraires" is the tariff; "Facturé" only counts once the
        // interview is billed, so summing that column matches the
        // dashboard's billed revenue.
        let fee = config.act_total(r.kind, r.fee_year, r.fee_rank, r.remote);
        let billed = if r.state == InterviewState::Billed {
            fee
        } else {
            0.0
        };
        out.push_str(&format!(
            "{};{};{};{};{};{};{};{};{};{};{};{};{};{};{};{};{};{};{}\r\n",
            field(&r.patient_name),
            field(&r.phone),
            db::format_french_date(&r.birth_date),
            r.kind.label(),
            r.kind.act_code(r.fee_year).unwrap_or(""),
            r.fee_year + 1,
            field(
                r.kind
                    .step_label(r.fee_year, r.fee_rank)
                    .unwrap_or(&rank_label(r.fee_rank))
            ),
            // Même règle que sur le papier : un acte qui ne porte pas
            // de thème n'en exporte pas, même si la base en garde un
            // d'une version qui l'écrivait quand même.
            field(if r.kind.has_theme() { &r.theme } else { "" }),
            r.state.label(),
            db::format_french_date(&r.created_date),
            field(&r.operator),
            r.scheduled_date
                .as_deref()
                .map(db::format_french_date)
                .unwrap_or_default(),
            // Et une durée n'a de sens que là où l'on en saisit une :
            // un TROD est chronométré par la bandelette, et « 0 » dans
            // cette colonne affirmerait un acte de zéro minute.
            if r.kind.has_duration() {
                r.duration_minutes.to_string()
            } else {
                String::new()
            },
            if r.remote { db::REMOTE_CODE } else { "" },
            if r.treatment_change && r.kind.allows_treatment_change() {
                tr("csv_yes")
            } else {
                ""
            },
            field(
                db::situation_label(&r.situation)
                    .map(tr)
                    .unwrap_or(&r.situation)
            ),
            comma(fee),
            r.kind.coverage_rate(),
            comma(billed),
        ));
    }
    out
}

/// The acts still to invoice — performed but not yet billed — turned
/// into the lines of the printable recap.
fn billing_lines(rows: &[db::ExportRow], config: &Config) -> Vec<crate::pdf::BillingLine> {
    rows.iter()
        .filter(|r| r.state == InterviewState::Performed)
        .map(|r| crate::pdf::BillingLine {
            date: r
                .scheduled_date
                .clone()
                .unwrap_or_else(|| r.created_date.clone()),
            patient: r.patient_name.clone(),
            kind: r.kind.label().to_owned(),
            code: r.kind.act_code(r.fee_year).unwrap_or("—").to_owned(),
            step: r
                .kind
                .step_label(r.fee_year, r.fee_rank)
                .map(|s| s.to_owned())
                .unwrap_or_else(|| rank_label(r.fee_rank)),
            situation: db::situation_label(&r.situation)
                .map(|k| tr(k).to_owned())
                .unwrap_or_else(|| r.situation.clone()),
            remote: r.remote,
            coverage: r.kind.coverage_rate(),
            fee: config.act_total(r.kind, r.fee_year, r.fee_rank, r.remote),
        })
        .collect()
}

/// A multiline field that keeps the height it is given. `TextEdit`
/// grows with its content, so a field holding a full monograph section
/// overran the rows under it and drew over their labels; the text
/// scrolls inside a fixed sunken box instead.
fn field_box(ui: &mut egui::Ui, id: &str, width: f32, height: f32, text: &mut String) {
    let (rect, _) = ui.allocate_exact_size(egui::vec2(width, height), egui::Sense::hover());
    motif::bevel(ui.painter(), rect, false);
    let inner = rect.shrink(3.0);
    let mut child = ui.new_child(egui::UiBuilder::new().max_rect(inner));
    egui::ScrollArea::vertical()
        .id_salt(id)
        .max_height(inner.height())
        .auto_shrink([false, false])
        .show(&mut child, |ui| {
            ui.add(
                egui::TextEdit::multiline(text)
                    .desired_width(inner.width() - 8.0)
                    .frame(false),
            );
        });
}

/// The clinical half of the editable drug card.
